//! Embeds the application icon, the per-format file icons and version information into
//! rustimgmount.exe. The icons are generated by assets/make_icon.py and
//! assets/make_format_icons.py.

fn main() {
    println!("cargo:rerun-if-changed=assets/rustimgmount.ico");
    println!("cargo:rerun-if-changed=assets/formats");
    // File icons: assets/formats/<ext>.ico becomes icon resource 101, 102, ... in name order.
    // The list is handed to the program (winutil.rs), which registers "<exe>,-<id>" per file type.
    let mut formats: Vec<(String, std::path::PathBuf)> = std::fs::read_dir("assets/formats")
        .map(|d| d.flatten().map(|e| e.path()).filter(|p| p.extension().is_some_and(|x| x == "ico")).collect::<Vec<_>>())
        .unwrap_or_default()
        .into_iter()
        .map(|p| (p.file_stem().unwrap_or_default().to_string_lossy().to_lowercase(), p))
        .collect();
    formats.sort();
    let table: String = formats.iter().enumerate().map(|(i, (ext, _))| format!("    (\"{ext}\", {}),\n", 101 + i)).collect();
    let out = std::path::Path::new(&std::env::var("OUT_DIR").unwrap()).join("format_icons.rs");
    std::fs::write(out, format!("/// (file extension, icon resource id in rustimgmount.exe)\npub const FORMAT_ICONS: &[(&str, u32)] = &[\n{table}];\n")).unwrap();
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let mut res = winresource::WindowsResource::new();
    for (i, (_, path)) in formats.iter().enumerate() {
        res.set_icon_with_id(&path.to_string_lossy(), &(101 + i).to_string());
    }
    // (Set last and with the lowest id, so it stays the program's own icon.)
    res.set_icon("assets/rustimgmount.ico")
        .set("FileDescription", "rustimgmount - mount disk images on Windows")
        .set("ProductName", "rustimgmount")
        .set("OriginalFilename", "rustimgmount.exe")
        .set("InternalName", "rustimgmount")
        // Modern common controls (task dialogs with progress bars), DPI awareness, and an
        // explicit "run as the invoking user" so Windows never guesses at elevation.
        .set_manifest(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
  <dependency>
    <dependentAssembly>
      <assemblyIdentity type="win32" name="Microsoft.Windows.Common-Controls" version="6.0.0.0"
        processorArchitecture="*" publicKeyToken="6595b64144ccf1df" language="*"/>
    </dependentAssembly>
  </dependency>
  <trustInfo xmlns="urn:schemas-microsoft-com:asm.v3">
    <security><requestedPrivileges><requestedExecutionLevel level="asInvoker" uiAccess="false"/></requestedPrivileges></security>
  </trustInfo>
  <application xmlns="urn:schemas-microsoft-com:asm.v3">
    <windowsSettings>
      <dpiAware xmlns="http://schemas.microsoft.com/SMI/2005/WindowsSettings">true/pm</dpiAware>
      <dpiAwareness xmlns="http://schemas.microsoft.com/SMI/2016/WindowsSettings">PerMonitorV2</dpiAwareness>
    </windowsSettings>
  </application>
</assembly>"#,
        );
    // A missing resource compiler should not stop the program from building.
    if let Err(e) = res.compile() {
        println!("cargo:warning=could not embed the icon: {e}");
    }
}
